'use strict';

// MODULES //

var isRowMajor = require( '@stdlib/ndarray/base/assert/is-row-major-string' );
var cfill = require( '@stdlib/blas/ext/base/cfill' ).ndarray;
var cscal = require( '@stdlib/blas/base/cscal' ).ndarray;
var realf = require( '@stdlib/complex/float32/real' );
var imagf = require( '@stdlib/complex/float32/imag' );
var f32 = require( '@stdlib/number/float64/base/to-float32' );
var reinterpret = require( '@stdlib/strided/base/reinterpret-complex64' );
var muladd = require( '@stdlib/complex/float32/base/mul-add' ).assign;


// MAIN //

/**
* Performs the matrix-vector operation `y = α*A*x + β*y`, where `α` and `β` are scalars, `x` and `y` are `N` element vectors, and `A` is an `N` by `N` Hermitian matrix supplied in packed form.
*
* @private
* @param {string} order - storage layout
* @param {string} uplo - specifies whether `A` is an upper or lower triangular part of matrix is supplied.
* @param {NonNegativeInteger} N - number of elements along each dimension of `A`
* @param {Complex64} alpha - scalar constant
* @param {Complex64Array} AP - input matrix in packed form
* @param {integer} strideAP - `AP` stride length
* @param {NonNegativeInteger} offsetAP - starting index for `AP`
* @param {Complex64Array} x - first input vector
* @param {integer} strideX - `x` stride length
* @param {NonNegativeInteger} offsetX - starting index for `x`
* @param {Complex64} beta - scalar constant
* @param {Complex64Array} y - second input vector
* @param {integer} strideY - `y` stride length
* @param {NonNegativeInteger} offsetY - starting index for `y`
* @returns {Complex64Array} `y`
*
* @example
* var Complex64Array = require( '@stdlib/array/complex64' );
* var Complex64 = require( '@stdlib/complex/float32/ctor' );
*
* var AP = new Complex64Array( [ 1.0, 0.0, 2.0, -2.0, 4.0, 0.0, 3.0, -3.0, 5.0, -5.0, 6.0, 0.0 ] );
* var x = new Complex64Array( [ 1.0, 1.0, 2.0, 2.0, 3.0, 3.0 ] );
* var y = new Complex64Array( [ 3.0, 3.0, 2.0, 2.0, 1.0, 1.0 ] );
* var alpha = new Complex64( 0.5, 0.5 );
* var beta = new Complex64( 0.5, -0.5 );
*
* chpmv( 'row-major', 'lower', 3, alpha, AP, 1, 0, x, 1, 0, beta, y, 1, 0 );
* // y => <Complex64Array>[ -10.0, 14.0, -11.0, 25.0, 14.0, 31.0 ]
*/
function chpmv( order, uplo, N, alpha, AP, strideAP, offsetAP, x, strideX, offsetX, beta, y, strideY, offsetY ) { // eslint-disable-line max-params, max-len
	var realpha;
	var imalpha;
	var rebeta;
	var imbeta;
	var retmp1;
	var imtmp1;
	var retmp2;
	var imtmp2;
	var viewAP;
	var viewX;
	var viewY;
	var cimap;
	var isrm;
	var sign;
	var reap;
	var imap;
	var iap;
	var sap;
	var rex;
	var imx;
	var ix0;
	var ix1;
	var iy0;
	var iy1;
	var i0;
	var i1;
	var oa;
	var ox;
	var oy;
	var sx;
	var sy;
	var kk;

	// Note on variable naming convention: sa#, ix#, i# where # corresponds to the loop number, with `0` being the innermost loop...

	isrm = isRowMajor( order );

	// Decompose scalars into real and imaginary components:
	rebeta = realf( beta );
	imbeta = imagf( beta );
	realpha = realf( alpha );
	imalpha = imagf( alpha );

	// y = beta*y
	if ( rebeta === 0.0 && imbeta === 0.0 ) {
		cfill( N, beta, y, strideY, offsetY );
	} else if ( rebeta !== 1.0 || imbeta !== 0.0 ) {
		cscal( N, beta, y, strideY, offsetY );
	}
	if ( realpha === 0.0 && imalpha === 0.0 ) {
		return y;
	}
	// Reinterpret arrays as real-valued views of interleaved real and imaginary components:
	viewAP = reinterpret( AP, 0 );
	viewX = reinterpret( x, 0 );
	viewY = reinterpret( y, 0 );
	if ( isrm ) {
		sign = -1;
	} else {
		sign = 1;
	}
	oa = offsetAP * 2;
	ox = offsetX * 2;
	oy = offsetY * 2;
	sx = strideX * 2;
	sy = strideY * 2;
	sap = strideAP * 2;

	// Form: y = alpha*A*x + y
	kk = oa;
	ix1 = ox;
	iy1 = oy;
	if ( ( isrm && uplo === 'upper' ) || ( !isrm && uplo === 'lower' ) ) {
		for ( i1 = 0; i1 < N; i1++ ) {
			rex = viewX[ ix1 ];
			imx = viewX[ ix1+1 ];
			retmp1 = f32(f32(realpha*rex) - f32(imalpha*imx));
			imtmp1 = f32(f32(realpha*imx) + f32(imalpha*rex));
			retmp2 = 0.0;
			imtmp2 = 0.0;
			reap = viewAP[ kk ];
			viewY[ iy1 ] = f32(viewY[ iy1 ] + (retmp1*reap));
			viewY[ iy1+1 ] = f32(viewY[ iy1+1 ] + (imtmp1*reap));
			ix0 = ix1 + sx;
			iy0 = iy1 + sy;
			iap = kk + sap;
			for ( i0 = i1 + 1; i0 < N; i0++ ) {
				reap = viewAP[ iap ];
				imap = viewAP[ iap+1 ];
				cimap = sign * imap;
				muladd( retmp1, imtmp1, reap, cimap, viewY[ iy0 ], viewY[ iy0+1 ], viewY, 1, iy0 ); // eslint-disable-line max-len
				rex = viewX[ ix0 ];
				imx = viewX[ ix0+1 ];
				retmp2 = f32(retmp2 + f32(reap*rex) + f32(cimap*imx));
				imtmp2 = f32(imtmp2 + f32(reap*imx) - f32(cimap*rex));
				ix0 += sx;
				iy0 += sy;
				iap += sap;
			}
			muladd( realpha, imalpha, retmp2, imtmp2, viewY[ iy1 ], viewY[ iy1+1 ], viewY, 1, iy1 ); // eslint-disable-line max-len
			ix1 += sx;
			iy1 += sy;
			kk += (N-i1) * sap;
		}
		return y;
	}
	// ( isrm && uplo === 'lower' ) || ( !isrm && uplo === 'upper' )
	for ( i1 = 0; i1 < N; i1++ ) {
		rex = viewX[ ix1 ];
		imx = viewX[ ix1+1 ];
		retmp1 = f32(f32(realpha*rex) - f32(imalpha*imx));
		imtmp1 = f32(f32(realpha*imx) + f32(imalpha*rex));
		retmp2 = 0.0;
		imtmp2 = 0.0;
		ix0 = ox;
		iy0 = oy;
		iap = kk;
		for ( i0 = 0; i0 < i1; i0++ ) {
			reap = viewAP[ iap ];
			imap = viewAP[ iap+1 ];
			cimap = sign * imap;
			muladd( retmp1, imtmp1, reap, cimap, viewY[ iy0 ], viewY[ iy0+1 ], viewY, 1, iy0 ); // eslint-disable-line max-len
			rex = viewX[ ix0 ];
			imx = viewX[ ix0+1 ];
			retmp2 = f32(retmp2 + f32(reap*rex) + f32(cimap*imx));
			imtmp2 = f32(imtmp2 + f32(reap*imx) - f32(cimap*rex));
			ix0 += sx;
			iy0 += sy;
			iap += sap;
		}
		reap = viewAP[ iap ];
		viewY[ iy1 ] = f32(viewY[ iy1 ] + (retmp1*reap));
		viewY[ iy1+1 ] = f32(viewY[ iy1+1 ] + (imtmp1*reap));
		muladd( realpha, imalpha, retmp2, imtmp2, viewY[ iy1 ], viewY[ iy1+1 ], viewY, 1, iy1 ); // eslint-disable-line max-len
		ix1 += sx;
		iy1 += sy;
		kk += (i1+1) * sap;
	}
	return y;
}


// EXPORTS //

module.exports = chpmv;
